-- BIB 101 unit 1, part 4 of 6

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-101';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Holiness and the Wilderness: Leviticus, Numbers and Deuteronomy$j$, $j${"readings": [], "body": "Read Leviticus 19:1 to 4, Numbers 6:22 to 27 and Deuteronomy 6:1 to 9 in the King James Version. Then read this lesson.\n\nAfter Sinai, Israel built the tabernacle, the tent where God's presence dwelt among them. Leviticus is the book of worship and holiness. It explains the offerings, the work of the priests, the Day of Atonement and the feasts, and it repeats the call to be a holy people. Numbers records the counting of the tribes and the long journey toward the promised land. When Israel refused to trust God at the border, that generation wandered in the wilderness for forty years. Deuteronomy means second law. It records Moses' farewell sermons to the new generation, calling them to love the LORD with all their heart. Moses saw the land from Mount Nebo and died, and Joshua took his place.\n\nThe first five books of the Bible are called the Law, or the Pentateuch.\n\nKey words: tabernacle, priest, holy, atonement, wilderness.\n\nYour task: (1) Say why Israel wandered forty years. (2) Write Deuteronomy 6:5 from memory or from your Bible. (3) Name the five books of the Law in order.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "We are ending our first unit, the five books of the Law. Today we cover the last three: Leviticus, Numbers and Deuteronomy.\n\nAfter the great rescue and the covenant at Sinai, God gave Moses a pattern for a tent called the tabernacle. It was the place where God's presence dwelt among His people. Leviticus is the handbook for that worship. It describes the offerings, the work of the priests from the family of Aaron, and the Day of Atonement, when sin was dealt with once a year. Leviticus 19:2 gives the heart of the book, Ye shall be holy: for I the LORD your God am holy. Holy means set apart for God. Israel was to live differently from the nations around them.\n\nNumbers begins with a census, a counting of the tribes, and then the journey toward the promised land. At the border, twelve spies went in. Ten came back afraid and said the people were too strong. Only Caleb and Joshua said God would give them the land. Because Israel refused to trust God, that generation wandered in the wilderness for forty years. Even there, God provided food and water and led them by a cloud by day and fire by night. In Numbers 6 God gave the priests a blessing to speak over His people, The LORD bless thee, and keep thee: The LORD make his face shine upon thee, and be gracious unto thee: The LORD lift up his countenance upon thee, and give thee peace.\n\nDeuteronomy means second law. Forty years later, a new generation stood across the Jordan, and Moses preached his last sermons to them. He reminded them of God's works and called them to obey. The heart of his message is in Deuteronomy 6:4 and 5, Hear, O Israel: The LORD our God is one LORD: And thou shalt love the LORD thy God with all thine heart, and with all thy soul, and with all thy might. Israel still says those words every day.\n\nMoses climbed Mount Nebo and saw the land from a distance, and he died there. Joshua was chosen to lead the people in.\n\nThose five books, Genesis, Exodus, Leviticus, Numbers and Deuteronomy, are called the Law, or the Pentateuch. Your task is to explain the forty years, write Deuteronomy 6:5, and name the five books in order. Then take the four question check and the Unit 1 quiz.\n\nHoliness begins with loving God above all else. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Holiness and the Wilderness: Leviticus, Numbers and Deuteronomy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: The Covenant Thread$j$, $j${"prompt": "Choose one covenant moment from this unit: God's promise to Abram (Genesis 12:1 to 3), the Passover (Exodus 12), or the giving of the commandments (Exodus 20). Write one paragraph of 150 to 200 words. State what God promised or commanded, tell what the people were asked to do in response, and explain one thing the passage shows about the character of God. Quote at least one verse from the King James Version.", "rubric": "Total 100. Accurate summary of what God promised or commanded: 30. Describes the people's response: 20. Shows what the passage reveals about God, with a quoted King James Version verse: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: The Covenant Thread$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Promises Kept$j$, $j${"prompt": "God made promises to Abraham that took generations to fulfill. Think about a time you waited for something promised, or someone who kept a promise to you over a long time. Describe it, and explain what waiting taught you about trust. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Promises Kept$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Beginnings: Creation and the Fall$j$, $j${"questions": [{"q": "What does the word Genesis mean?", "options": ["Judges", "Laws", "Beginnings", "Journeys"]}, {"q": "On which day of creation did God make man?", "options": ["The seventh day", "The sixth day", "The third day", "The fifth day"]}, {"q": "From which tree did God command Adam not to eat?", "options": ["The tree of life", "The tree of the knowledge of good and evil", "Every tree in the garden", "The fig tree"]}, {"q": "Which verse holds the first promise of a coming deliverer?", "options": ["Genesis 1:1", "Genesis 4:1", "Genesis 3:15", "Genesis 2:7"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Beginnings: Creation and the Fall$j$);
end
$seed$;
